"use strict";Behaviours.add("form:wpcf7:init",t=>{Behaviours.remove("form:wpcf7:init"),typeof wpcf7!="undefined"&&Behaviours.add("form:wpcf7:init",e=>{e.querySelectorAll(".wpcf7 > form").forEach(wpcf7.init)})}),window.addEventListener("wpcf7invalid",t=>{requestAnimationFrame(()=>{let e=t.target.querySelector(".wpcf7-not-valid");if(e){for(e.focus();(e.currentStyle||getComputedStyle(e,null)).display==="none";){if(!e.parentElement)return;e=e.parentElement}e.scrollIntoView({block:"center"})}})});
